using System.Text.Json;
using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Xunit;

namespace MyApp.Evaluation;

public class EvaluationTests : IAsyncLifetime
{
    private DistributedApplicationTestingBuilder _builder = null!;
    private DistributedApplication _app = null!;

    public async ValueTask InitializeAsync()
    {
        _builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _builder.BuildAsync();
        await _app.StartAsync();
    }

    public async ValueTask DisposeAsync()
    {
        await _app.DisposeAsync();
    }

    [Fact]
    public async Task RunEvaluationScenarios()
    {
        var scenarios = EvaluationScenarioLoader.Load("evaluation.yml");
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var results = new List<ScenarioResult>();

        foreach (var scenario in scenarios)
        {
            var chatHistory = new List<ChatMessage>();

            ChatResponse? response = null;
            foreach (var turn in scenario.Turns)
            {
                chatHistory.Add(new ChatMessage(ChatRole.User, turn.User));
                response = await chatClient.GetResponseAsync(chatHistory);
                chatHistory.Add(response.Message);
            }

            var result = new ScenarioResult
            {
                Name = scenario.Name,
                Description = scenario.Description,
                Response = response?.Message.Text ?? string.Empty,
                Passed = true
            };

            results.Add(result);
        }

        var json = JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        await File.WriteAllTextAsync("evaluation-results.json", json);

        Assert.All(results, r => Assert.True(r.Passed, $"Scenario '{r.Name}' failed."));
    }
}

public class ScenarioResult
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Response { get; set; } = string.Empty;
    public bool Passed { get; set; }
}

using System.Text.RegularExpressions;

namespace MyApp.Evaluation;

/// <summary>
/// Loads evaluation scenarios from a YAML configuration file.
/// Uses a lightweight parser to avoid external YAML dependencies.
/// </summary>
public static class EvaluationScenarioLoader
{
    public static List<EvaluationScenario> Load(string path)
    {
        var content = File.ReadAllText(path);
        var scenarios = new List<EvaluationScenario>();

        var scenarioBlocks = Regex.Split(content, @"(?=^\s{2}- name:)", RegexOptions.Multiline);

        foreach (var block in scenarioBlocks)
        {
            var nameMatch = Regex.Match(block, @"- name:\s*(.+)");
            if (!nameMatch.Success) continue;

            var scenario = new EvaluationScenario
            {
                Name = nameMatch.Groups[1].Value.Trim()
            };

            var descMatch = Regex.Match(block, @"description:\s*(.+)");
            if (descMatch.Success)
                scenario.Description = descMatch.Groups[1].Value.Trim();

            var turnMatches = Regex.Matches(block, @"- user:\s*""(.+?)""");
            foreach (Match turn in turnMatches)
            {
                scenario.Turns.Add(new EvaluationTurn { User = turn.Groups[1].Value });
            }

            var criteriaMatches = Regex.Matches(block, @"- metric:\s*(\w+)\s+threshold:\s*([\d.]+)");
            foreach (Match criterion in criteriaMatches)
            {
                scenario.Criteria.Add(new EvaluationCriterion
                {
                    Metric = criterion.Groups[1].Value,
                    Threshold = double.Parse(criterion.Groups[2].Value)
                });
            }

            scenarios.Add(scenario);
        }

        return scenarios;
    }
}

public class EvaluationScenario
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<EvaluationTurn> Turns { get; set; } = new();
    public List<EvaluationCriterion> Criteria { get; set; } = new();
}

public class EvaluationTurn
{
    public string User { get; set; } = string.Empty;
}

public class EvaluationCriterion
{
    public string Metric { get; set; } = string.Empty;
    public double Threshold { get; set; }
}

